mapper.update:
UPDATE sys_user
SET real_name = #{realName}, phone = #{phone}, email = #{email}, updated_at = now()
WHERE id = #{id}

mapper.select:
SELECT r.role_code FROM sys_role r
JOIN sys_user_role ur ON ur.role_id = r.id
WHERE ur.user_id = #{userId}

SELECT r.role_name FROM sys_role r
JOIN sys_user_role ur ON ur.role_id = r.id
WHERE ur.user_id = #{userId}

mapper.insert:
INSERT INTO sys_user_role (user_id, role_id)
SELECT #{userId}, id FROM sys_role WHERE role_code = #{roleCode}
ON CONFLICT DO NOTHING

mapper.select:
SELECT id, username, real_name, phone, status, created_at
FROM sys_user WHERE invited_by = #{inviterId}
ORDER BY created_at DESC
